#include <iostream>
#include <vector>
#include <queue>
#include <cmath>
#include <stdexcept>

class InputReader {
private:
    std::istream& stream;
    static const int buf_size = 8192;
    char buf[buf_size];
    int curChar, snumChars;

public:
    InputReader(std::istream& st) : stream(st), curChar(0), snumChars(0) {}

    int read() {
        if (snumChars == -1)
            throw std::runtime_error("InputMismatchException");
        if (curChar >= snumChars) {
            stream.read(buf, buf_size);
            snumChars = stream.gcount();
            if (snumChars <= 0)
                return -1;
            curChar = 0;
        }
        return static_cast<unsigned char>(buf[curChar++]);
    }

    int nextInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            res = res * 10 + (c - '0');
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    long long nextLong() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        long long res = 0;
        do {
            res = res * 10 + (c - '0');
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    std::vector<int> nextIntArray(int n) {
        std::vector<int> a(n);
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
        }
        return a;
    }

    std::string readString() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        std::string res;
        do {
            res += static_cast<char>(c);
            c = read();
        } while (!isEndOfLine(c));
        return res;
    }

    std::string nextLine() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        std::string res;
        do {
            res += static_cast<char>(c);
            c = read();
        } while (!isEndOfLine(c));
        return res;
    }

    bool isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    bool isEndOfLine(int c) {
        return c == '\n' || c == '\r' || c == -1;
    }
};

int main() {
    InputReader in(std::cin);
    int n = in.nextInt();
    int b = in.nextInt();
    std::vector<int> a = in.nextIntArray(n);
    std::vector<int> odd(n + 1, 0);
    std::vector<int> even(n + 1, 0);
    for (int i = 1; i <= n; i++) {
        if (a[i - 1] % 2 == 1) {
            odd[i] = odd[i - 1] + 1;
            even[i] = even[i - 1];
        } else {
            odd[i] = odd[i - 1];
            even[i] = even[i - 1] + 1;
        }
    }
    int prev = 0;
    std::priority_queue<int, std::vector<int>, std::greater<int>> cost;
    for (int i = 1; i <= n - 1; i++) {
        int oc = odd[i] - odd[prev];
        int ec = even[i] - even[prev];
        if (oc == ec) {
            cost.push(std::abs(a[i] - a[i - 1]));
            prev = i;
        }
    }
    int sum = 0;
    int count = 0;
    while (!cost.empty() && sum <= b) {
        sum += cost.top();
        cost.pop();
        count++;
    }
    if (count == 0) {
        std::cout << "0\n";
    } else {
        if (cost.empty() && sum <= b) {
            std::cout << count << "\n";
        } else {
            std::cout << count - 1 << "\n";
        }
    }
    return 0;
}

