using namespace std;

class InputReader {
public:
    std::istream& in;
    std::string buffer;
    std::istringstream tokenizer;

    InputReader(std::istream& stream) : in(stream) {}

    std::string next() {
        while (!(tokenizer >> buffer)) {
            if (!std::getline(in, buffer))
                throw std::runtime_error("End of input");
            tokenizer.clear();
            tokenizer.str(buffer);
        }
        return buffer;
    }

    long long nextLong() {
        return std::stoll(next());
    }

    int nextInt() {
        return std::stoi(next());
    }
};

class Unstoppable {
public:
    void solve(InputReader& in, std::ostream& out) {
        int n = in.nextInt();
        long long b = in.nextLong();
        std::vector<int> a(n);
        std::vector<int> c(n);
        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
            if (a[i] % 2 == 0)
