            numOdds = 0;
            costs.push_back(std::abs(arr[i] - arr[i - 1]));
        }
        if (arr[i] % 2 == 0)
            ++numEvens;
        else
            ++numOdds;
    }
    std::sort(costs.begin(), costs.end());
    for (size_t i = 0; i < costs.size(); ++i) {
        if (b < costs[i])
            break;
        ++numCuttings;
        b -= costs[i];
    }
    return numCuttings;
}

int main() {
    int n, b;
    std::cin >> n >> b;
    std::vector<int> arr(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> arr[i];
    }
    std::cout << maxCuttings(arr, b) << std::endl;
    return 0;
}

