struct HopcroftKarp {
    int m, n;
    vector<vector<int>> g;
    vector<int> pairU, pairV, dis;
    const int inf = INT_MAX;
    const int NIL = 0;

    HopcroftKarp(int m_, int n_, const vector<vector<int>>& g_) : m(m_), n(n_), g(g_) {
        pairU.assign(m + 1, NIL);
        pairV.assign(n + 1, NIL);
        dis.assign(m + 1, 0);
    }

    int maximumMatching() {
        int matching = 0;
        while (bfs()) {
            for (int u = 1; u <= m; u++) {
                if (pairU[u] == NIL && dfs(u))
                    matching++;
            }
        }
        return matching;
    }

private:
    bool bfs() {
        queue<int> q;
        for (int u = 1; u <= m; u++) {
            if (pairU[u] == NIL) {
                dis[u] = 0;
                q.push(u);
            } else {
                dis[u] = inf;
            }
