    vector<vector<int>> mat(n + 1, vector<int>(m + 1, 0));
    int u = 1, v = 1;

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if ((i + j) % 2 == 0) {
                mat[i][j] = u++;
            }
        }
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if ((i + j) % 2 != 0) {
                mat[i][j] = v++;
            }
        }
    }

    vector<vector<int>> g(u, vector<int>());
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if ((i + j) % 2 == 0) {
                auto addEdge = [&](int si, int sj, int ti, int tj) {
                    if (ti >= 1 && ti <= n && tj >= 1 && tj <= m) {
                        g[mat[si][sj]].push_back(mat[ti][tj]);
                    }
                };
                addEdge(i, j, i - 3, j);
                addEdge(i, j, i - 2, j - 1);
                addEdge(i, j, i - 2, j + 1);
                addEdge(i, j, i, j - 3);
                addEdge(i, j, i - 1, j - 2);
                addEdge(i, j, i + 1, j - 2);
                addEdge(i, j, i, j + 3);
                addEdge(i, j, i - 1, j + 2);
                addEdge(i, j, i + 1, j + 2);
                addEdge(i, j, i + 3, j);
                addEdge(i, j, i + 2, j - 1);
                addEdge(i, j, i + 2, j + 1);
            }
        }
    }

    HopcroftKarp bpm(u - 1, v - 1, g);
    ans += 2LL * bpm.maximumMatching();

    out.println(ans);
    return 0;
}

