        else if (n == 1) {
        	if (m % 6 == 0 || m % 6 == 1 || m % 6 == 2 || m % 6 == 3) {
        		pw.println(6*(m/6));
        	}
        	else if (m % 6 == 4) {
        		pw.println(6*(m/6)+2);
        	}
        	else if (m % 6 == 5) {
        		pw.println(6*(m/6)+4);
        	}
        }
        else if (m == 1) {
        	if (n % 6 == 0 || n % 6 == 1 || n % 6 == 2 || n % 6 == 3) {
        		pw.println(6*(n/6));
        	}
        	else if (m % 6 == 4) {
        		pw.println(6*(n/6)+2);
        	}
        	else if (m % 6 == 5) {
        		pw.println(6*(n/6)+4);
        	}
        }
        else if (n == 2 && m == 2) {
        	pw.println(0);
        }
        else if (n == 2 && m == 3 || n == 3 && m == 2) {
        	pw.println(4);
        }
        else if (n == 2 && m == 7 || n == 7 && m == 2) {
        	pw.println(12);
        }
        else if (n % 2 == 0 || m % 2 == 0) {
        	pw.println(n*m);
        }
        else {
        	pw.println(n*m-1);
        }

        pw.close();
    }
    static class FastScanner {
    	private boolean finished = false;

        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw   new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }
        public int peek() {
            if (numChars == -1) {
                return -1;
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    return -1;
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }
        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
