    occ[0]++;
    nbr_vertexes[0] = 1;
    for (int i = 1; i <= n; i++) {
        vector<long> oc(n / 2 + 1, 0);
        int limite = min(n - i, n / 2);
        for (int j = 0; j <= limite; j++) {
            long h = occ[j];
            if (j + 1 <= limite) {
                oc[j + 1] += h;
                oc[j + 1] %= big;
            }
            if (j - 1 >= 0) {
                oc[j - 1] += h;
                oc[j - 1] %= big;
            }
            oc[j] %= big;
        }
        if (limite + 1 <= n / 2) {
            oc[limite] += occ[limite + 1];
            oc[limite] %= big;
        }
        long sum = 0;
        for (int j = 0; j <= limite; j++) {
            sum += oc[j];
            sum %= big;
            occ[j] = oc[j];
        }
        nbr_vertexes[i] = sum;
    }
