        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[][] ways = new long[n * 2][n + 1];
        long tWays = 0;
        ways[0][0] = 1;
        for (int i = 1; i < 2 * n; i++) {
            ways[i][0] = ways[i - 1][1];
            ways[i][n] = ways[i - 1][n - 1];
