vector<vector<long long>> iden(int n) {
    vector<vector<long long>> res(n, vector<long long>(n, 0));
    for (int i = 0; i < n; i++) {
        res[i][i] = 1;
    }
    return res;
}

vector<vector<long long>> mult(const vector<vector<long long>>& a, const vector<vector<long long>>& b) {
    int n = a.size();
    int m = b[0].size();
    int k = a[0].size();
    vector<vector<long long>> res(n, vector<long long>(m, 0));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            for (int t = 0; t < k; t++) {
                res[i][j] += (a[i][t] % mod) * (b[t][j] % mod);
                res[i][j] %= mod;
            }
        }
    }
    return res;
}

vector<vector<long long>> pow(const vector<vector<long long>>& a, long long p) {
    if (p == 0) return iden(a.size());
    if (p % 2 == 1) {
        auto res = pow(a, p - 1);
        return mult(res, a);
    }
    auto res = pow(a, p / 2);
    return mult(res, res);
}

