            }
        }
        for(int i = 0;i < n; i++){
            for(int j = 0;j < n; j++){
                for(int k = 0; k < 5; k++){
                    vect[i][j][k] = coord[j][k] - coord[i][k];
                }
            }
        }
        int count = n;
        long prod;
        for(int i = 0;i < n; i++){
            for(int j = 0;j < n; j++){
                if(j != i){
                    for(int k = 0; k < n; k++){
                        if(k != j && k != i){
                            prod = 0;
                            for(int m = 0; m < 5; m++){
                                prod += vect[j][i][m]*vect[k][i][m];
                            }
