    std::cin >> s;

    int winpars = 0, longest = 0;
    int i = 0, j = 0;

    // Replace all "__" with "_"
    while (s.find("__") != std::string::npos) {
        size_t pos = s.find("__");
        s.replace(pos, 2, "_");
    }

    n = s.length();

    // Process first parentheses block
    if (i < n && s[i] == '(') {
        j = i;
        while (j < n && s[j] != ')') {
            ++j;
        }
        if (j < n && s[j] == ')') {
            std::string temp = s.substr(i + 1, j - i - 1);
            if (temp.find('_') == std::string::npos && temp.length() > 0) {
                ++winpars;
            } else {
                std::stringstream ss(temp);
                std::string token;
                while (std::getline(ss, token, '_')) {
                    if (!token.empty()) {
                        ++winpars;
                    }
                }
            }
            i = j + 1;
        }
    }

    // Process remaining parentheses blocks
    while (i < n) {
        if (s[i] == '(') {
            j = i;
            while (j < n && s[j] != ')') {
                ++j;
            }
            if (j < n && s[j] == ')') {
                std::string temp = s.substr(i + 1, j - i - 1);
                if (temp.find('_') == std::string::npos && temp.length() > 0) {
                    ++winpars;
                } else {
                    std::stringstream ss(temp);
                    std::string token;
                    while (std::getline(ss, token, '_')) {
                        if (!token.empty()) {
                            ++winpars;
                        }
                    }
                }
                i = j + 1;
            } else {
                ++i;
            }
        } else {
            ++i;
        }
    }

    // Replace all parentheses with "_"
    while (true) {
        size_t start_pos = s.find('(');
        size_t end_pos = s.find(')');
        if (start_pos == std::string::npos || end_pos == std::string::npos) {
            break;
        }
        s.replace(start_pos, end_pos - start_pos + 1, "_");
    }

    // Tokenize by "_"
    std::stringstream ss(s);
    std::string token;
    while (std::getline(ss, token, '_')) {
        if (token.length() > longest) {
            longest = token.length();
        }
    }

    std::cout << longest << " " << winpars << "\n";

    return 0;
}

