class TaskB {
public:
    void solve() {
        int n;
        cin >> n;
        string input;
        cin >> input;

        string pattern = "\\([\\w_]*\\)";
        regex r(pattern);
        sregex_iterator next(input.begin(), input.end(), r);
        sregex_iterator end;

        int longest = 0;
        long long numberInside = 0;

        // Find all matches
        for (sregex_iterator it = next; it != end; ++it) {
            string matchStr = it->str();
            string trimmed = trimParentheses(matchStr);
            // Count words inside underscores
            stringstream ss(trimmed);
            string word;
            while (getline(ss, word, '_')) {
                if (!word.empty()) {
                    ++numberInside;
                }
            }
        }

        // Split input by pattern to find longest segment
        vector<string> outSite;
        size_t lastPos = 0;
        auto words_begin = sregex_iterator(input.begin(), input.end(), r);
        auto words_end = sregex_iterator();

        for (auto it = words_begin; it != words_end; ++it) {
            size_t matchPos = it->position();
            string segment = input.substr(lastPos, matchPos - lastPos);
            outSite.push_back(segment);
            lastPos = matchPos + it->length();
        }
        // Add the remaining part after last match
        if (lastPos < input.size()) {
            outSite.push_back(input.substr(lastPos));
        }

        for (const auto& s : outSite) {
            int len = 0;
            stringstream ss(s);
            string word;
            while (getline(ss, word, '_')) {
                len = max(len, (int)word.length());
            }
            longest = max(longest, len);
        }

        cout << longest << " " << numberInside << "\n";
    }

private:
    string trimParentheses(const string& input) {
        if (input.size() >= 2 && input.front() == '(' && input.back() == ')') {
            return input.substr(1, input.size() - 2);
        }
        return input;
    }
};

