#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;
    std::cin.ignore(); // ignore the remaining newline after reading n
    std::string s;
    std::getline(std::cin, s);

    // Split string s by pattern "\\(.*?\\)"
    // Since C++ doesn't have a built-in regex split, we'll emulate it
    std::vector<std::string> p;
    size_t start = 0;
    size_t pos = 0;
    while ((pos = s.find('(', start)) != std::string::npos) {
        size_t end_pos = s.find(')', pos);
        if (end_pos == std::string::npos) {
            break; // no matching closing parenthesis
        }
        // Extract substring before '('
        if (pos > start) {
            p.push_back(s.substr(start, pos - start));
        }
        start = end_pos + 1;
    }
    // Add remaining part after last ')'
    if (start < s.size()) {
        p.push_back(s.substr(start));
    }

    int max_len = 0;
    for (const auto& part : p) {
        std::stringstream ss(part);
        std::string token;
        while (std::getline(ss, token, '_')) {
            max_len = std::max((int)token.length(), max_len);
        }
    }

    std::vector<std::string> li;
    char a = '(';
    char b = ')';
    int last = -1;
    for (size_t i = 0; i < s.length(); ++i) {
        char c = s[i];
        if (c == a) {
            last = i;
        } else if (c == b && last != -1) {
            // extract substring between last+1 and i
            if (last + 1 < (int)s.length()) {
                li.push_back(s.substr(last + 1, i - last - 1));
            }
        }
    }

    int count = 0;
    for (const auto& segment : li) {
        std::stringstream ss(segment);
        std::string word;
        while (std::getline(ss, word, '_')) {
            if (!word.empty()) {
                count++;
            }
        }
    }

    std::cout << max_len << " " << count << std::endl;
    return 0;
}

