class TaskB {
public:
    void solve() {
        int n;
        cin >> n;
        string input;
        cin >> input;

        string pattern = "\\([\\w_]*\\)";
        regex r(pattern);
        sregex_iterator it(input.begin(), input.end(), r);
        sregex_iterator end;

        int longest = 0;
        long long numberInside = 0;

        // Split input based on pattern
        vector<string> outSite;
        size_t lastPos = 0;
        for (auto it = sregex_iterator(input.begin(), input.end(), r); it != end; ++it) {
            size_t matchPos = it->position();
            size_t matchLen = it->length();
            outSite.push_back(input.substr(lastPos, matchPos - lastPos));
            lastPos = matchPos + matchLen;
        }
        // Add the remaining part after last match
        if (lastPos < input.size()) {
            outSite.push_back(input.substr(lastPos));
        }

        for (const auto& s : outSite) {
            longest = max(longest, longestWords(s));
        }

        for (auto it = sregex_iterator(input.begin(), input.end(), r); it != end; ++it) {
            string groupStr = it->str();
            string trimmed = trimParentheses(groupStr);
            string[] parts = split(trimmed, '_');
            for (const auto& part : parts) {
                if (!part.empty()) {
                    ++numberInside;
                }
            }
        }

        cout << longest << " " << numberInside << "\n";
    }

private:
    int longestWords(const string& line) {
        if (line.empty()) return 0;
        int maxLen = 0;
        stringstream ss(line);
        string token;
        while (getline(ss, token, '_')) {
            maxLen = max(maxLen, (int)token.length());
        }
        return maxLen;
    }

    string trimParentheses(const string& input) {
        if (input.length() <= 2) return "";
        return input.substr(1, input.length() - 2);
    }

    vector<string> split(const string& s, char delimiter) {
        vector<string> tokens;
        string token;
        stringstream ss(s);
        while (getline(ss, token, delimiter)) {
            tokens.push_back(token);
        }
        return tokens;
    }
};

