        if (end_idx == std::string::npos) {
            break;
        }
        std::string inside = st.substr(start_idx + 1, end_idx - start_idx - 1);
        std::istringstream inside_stream(inside);
        while (std::getline(inside_stream, token, '_')) {
            if (!token.empty()) {
                cnt++;
            }
        }
        i = end_idx + 1;
        j = i;
