		Scanner sc = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);
		int n = sc.nextInt();

		int count=0;
		int max=0;

		int start=-1;

		boolean in=false;
			String s=sc.next();
			for (int i = 0; i < s.length(); i++) {
//				System.out.println(start+" "+s.charAt(i)+" "+max +" "+count+" ");
				if(s.charAt(i)=='_'){

					if(start!=i-1)
						if(in)
							count++;
						else
							max=Math.max(max, i-1-start);

					start=i;

				}

				if(s.charAt(i)=='('){
					in=true;
					if(start!=i-1)
						max=Math.max(max, i-1-start);

					start=i;
				}
				if(s.charAt(i)==')'){
					in=false;
					if(start!=i-1)
						count++;
					start=i;
				}
			}
