int remove_underscore(std::string &str) {
    // Replace all underscores with spaces
    for (auto &ch : str) {
        if (ch == '_') ch = ' ';
    }
    // Trim leading and trailing spaces
    size_t start = str.find_first_not_of(' ');
    size_t end = str.find_last_not_of(' ');
    if (start == std::string::npos || end == std::string::npos) {
        str = "";
        return 0;
    }
    str = str.substr(start, end - start + 1);
    // Replace multiple spaces with a single space
    std::string result;
    bool in_space = false;
    for (char ch : str) {
        if (isspace(ch)) {
            if (!in_space) {
                result += ' ';
                in_space = true;
            }
        } else {
            result += ch;
            in_space = false;
        }
    }
    str = result;
    if (str.empty()) return 0;
    // Count words
    int count = 1;
    for (char ch : str) {
        if (ch == ' ') count++;
    }
    return count;
}

int main() {
    int n;
    std::cin >> n;
    std::string s;
    std::cin >> s;

    std::vector<int> braces_indices;
    braces_indices.push_back(-1);
    for (int i = 0; i < (int)s.length(); i++) {
        if (s[i] == '(' || s[i] == ')') {
            braces_indices.push_back(i);
        }
    }

    int count_inside_braces = 0;
    int maxl = 0;
    std::string outside_braces;

    for (size_t i = 1; i + 1 < braces_indices.size(); i += 2) {
        int open_brace_index = braces_indices[i];
        int close_brace_index = braces_indices[i + 1];
        std::string inside_braces = s.substr(open_brace_index + 1, close_brace_index - open_brace_index - 1);
        int count = remove_underscore(inside_braces);
        count_inside_braces += count;

        int prev_end = (i - 1 >= 0) ? braces_indices[i - 1] : -1;
        outside_braces += "_" + s.substr(prev_end + 1, open_brace_index - prev_end - 1);
    }

    // Append the last outside segment
    int last_brace_index = braces_indices.back();
    outside_braces += "_" + s.substr(last_brace_index + 1);

    // Process outside_braces
    for (auto &ch : outside_braces) {
        if (ch == '_') ch = ' ';
    }
    // Trim leading and trailing spaces
    size_t start = outside_braces.find_first_not_of(' ');
    size_t end = outside_braces.find_last_not_of(' ');
    if (start != std::string::npos && end != std::string::npos) {
        outside_braces = outside_braces.substr(start, end - start + 1);
    } else {
        outside_braces = "";
    }
    // Replace multiple spaces with a single space
    std::string cleaned;
    bool in_space = false;
    for (char ch : outside_braces) {
        if (isspace(ch)) {
            if (!in_space) {
                cleaned += ' ';
                in_space = true;
            }
        } else {
            cleaned += ch;
            in_space = false;
        }
    }
    outside_braces = cleaned;

    // Find maximum word length
    std::string s_new;
    size_t pos = 0;
    while ((pos = outside_braces.find(' ')) != std::string::npos) {
        s_new += outside_braces.substr(0, pos) + " ";
        outside_braces.erase(0, pos + 1);
    }
    s_new += outside_braces;

    std::istringstream iss(s_new);
    std::string word;
    while (iss >> word) {
        if ((int)word.length() > maxl) {
            maxl = word.length();
        }
    }

    std::cout << maxl << " " << count_inside_braces;
    return 0;
}

