static long long dp[51][51][201][2];
static int cap, fat, slim;
static long long ncr[51][51];

const int mod = 1000000007;

long long pathfinder(int fatsleft, int slimsleft, int ridesleft, bool boatpos) {
    if (fatsleft == 0 && slimsleft == 0 && ridesleft == 0)
        return 1;
    if (ridesleft == 0)
        return 0;
    if (dp[fatsleft][slimsleft][ridesleft][boatpos ? 0 : 1] != -1)
        return dp[fatsleft][slimsleft][ridesleft][boatpos ? 0 : 1];
    long long ways = 0;
    if (boatpos) {
        for (int i = 0; i <= fatsleft; i++) {
            for (int j = 0; j <= slimsleft; j++) {
                if (i + j > 0 && i * 2 + j <= cap) {
                    long long ways_add = (ncr[fatsleft][i] * ncr[slimsleft][j]) % mod;
                    ways_add = (ways_add * pathfinder(fatsleft - i, slimsleft - j, ridesleft - 1, false)) % mod;
                    ways = (ways + ways_add) % mod;
                }
            }
        }
    } else {
        for (int i = 0; i <= (fat - fatsleft); i++) {
            for (int j = 0; j <= (slim - slimsleft); j++) {
                if (i + j > 0 && i * 2 + j <= cap) {
                    long long ways_add = (ncr[fat - fatsleft][i] * ncr[slim - slimsleft][j]) % mod;
                    ways_add = (ways_add * pathfinder(fatsleft + i, slimsleft + j, ridesleft - 1, true)) % mod;
                    ways = (ways + ways_add) % mod;
                }
            }
        }
    }
    return dp[fatsleft][slimsleft][ridesleft][boatpos ? 0 : 1] = ways;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    cap = cin / 50;
    int total_fat = 0, total_slim = 0;
    vector<int> arr(n);
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
        if (arr[i] == 100)
            total_fat++;
        else
            total_slim++;
    }
    fat = total_fat;
    slim = total_slim;

    for (int i = 0; i <= fat; i++)
        for (int j = 0; j <= slim; j++)
            dp[i][j][0][0] = dp[i][j][0][1] = -1;

    for (int i = 0; i <= 50; i++)
        for (int j = 0; j <= i; j++)
            ncr[i][j] = 1;

    vector<long long> fact(51, 1);
    for (int i = 1; i <= 50; i++) {
        fact[i] = (fact[i - 1] * i) % mod;
