        long long result = 1;
        long long c = a % m;
        long long exp = b;
        while (exp > 0) {
            if (exp & 1)
                result = (result * c) % m;
            c = (c * c) % m;
            exp >>= 1;
        }
        return result;
    };

    for (int i = 0; i <= 50; i++) {
        for (int j = 0; j <= i; j++) {
