    result[0] = -1;
    while (i < (int)val.length()) {
        while (j >= 0 && val[j] != val[i]) {
            j = result[j];
        }
        j++;
        i++;
        result[i] = j;
    }
    return result;
}

bool nextPer(vector<int>& data) {
    int i = data.size() - 1;
    while (i > 0 && data[i] < data[i - 1]) {
        i--;
    }
    if (i == 0) {
        return false;
    }
    int j = data.size() - 1;
    while (data[j] < data[i - 1]) {
        j--;
    }
    swap(data[i - 1], data[j]);
    sort(data.begin() + i, data.end());
    return true;
}

int digit(long long n) {
    int result = 0;
    while (n > 0) {
        n /= 10;
        result++;
    }
    return result;
}

double dist(long long a, long long b, long long x, long long y) {
    double val = (b - a) * (b - a) + (x - y) * (x - y);
    val = sqrt(val);
    double other = x * x + a * a;
    other = sqrt(other);
    return val + other;
}

struct Point {
    int x, y;
    Point(int start, int end) : x(start), y(end) {}
    bool operator==(const Point& other) const {
        return x == other.x && y == other.y;
    }
    bool operator<(const Point& o) const {
        return x < o.x;
    }
};

struct FT {
    vector<long long> data;
    FT(int n) : data(n, 0) {}
    void update(int index, long long value) {
        while (index < (int)data.size()) {
            data[index] += value;
            index += index & (-index);
        }
    }
    long long get(int index) {
        long long result = 0;
        while (index > 0) {
            result += data[index];
            index -= index & (-index);
        }
        return result;
    }
};

long long gcd(long long a, long long b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}

long long powLL(long long a, long long b) {
    if (b == 0) return 1;
    if (b == 1) return a;
    long long val = powLL(a, b / 2);
    if (b % 2 == 0) {
        return (val * val) % MOD;
    } else {
        return (val * ((val * a) % MOD)) % MOD;
    }
}

