            numChars = stream.gcount();
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    int peek() {
        if (numChars == -1)
            return -1;
        if (curChar >= numChars) {
            curChar = 0;
            stream.read(buf.data(), buf.size());
            numChars = stream.gcount();
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar];
    }

    int readInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw std::runtime_error("InputMismatch");
            res = res * 10 + c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    long long readLong() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        long long res = 0;
        do {
            if (c < '0' || c > '9')
                throw std::runtime_error("InputMismatch");
            res = res * 10 + c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    std::string readString() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        std::string res;
        do {
            if (c != -1)
                res += (char)c;
            c = read();
        } while (!isSpaceChar(c));
        return res;
    }

    bool isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    double readDouble() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        double res = 0;
        while (!isSpaceChar(c) && c != '.') {
            if (c == 'e' || c == 'E')
                return res * pow(10, readInt());
            if (c < '0' || c > '9')
                throw std::runtime_error("InputMismatch");
            res = res * 10 + c - '0';
            c = read();
        }
        if (c == '.') {
            c = read();
            double m = 1;
            while (!isSpaceChar(c)) {
                if (c == 'e' || c == 'E')
                    return res * pow(10, readInt());
                if (c < '0' || c > '9')
                    throw std::runtime_error("InputMismatch");
                m /= 10;
                res += (c - '0') * m;
                c = read();
            }
        }
        return res * sgn;
    }

    std::string next() {
        return readString();
    }
};

class OutputWriter {
public:
    std::ostream& out;
    OutputWriter(std::ostream& s) : out(s) {}
    void printLine(int x) { out << x << "\n"; }
    void printLine(long long x) { out << x << "\n"; }
    void printLine() { out << "\n"; }
};

class Task {
public:
    virtual void solve(int testNumber, InputReader& in, OutputWriter& out) = 0;
    virtual ~Task() {}
};

class A : public Task {
public:
    void solve(int testNumber, InputReader& in, OutputWriter& out) override {
        std::string str = in.next();
        int ret = 0, n = (int)str.size(), c = 0;
        for (int i = 1; i < n; i++) {
            if (str[i] != str[i - 1]) {
                ret += c % 2;
                c = 0;
            } else {
                c++;
            }
        }
        ret += c % 2;
        out.printLine(ret);
    }
};

int main() {
    InputReader in(std::cin);
    OutputWriter out(std::cout);
    std::unique_ptr<Task> solver = std::make_unique<A>();
    solver->solve(1, in, out);
    return 0;
}

