        int mid = (l + r) / 2;
        if (list[mid] > val) {
            if (mid == 0) {
                return mid;
            }
            if (list[mid - 1] <= val) {
                return mid;
            }
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }
    return res;
}

static long long calc(vector<Node>& list, vector<long long>& b, int i) {
