    }

    long long readLong() {
        long long ans = 0;
        bool neg = false;
        char c;
        bool start = false;
        while (cin.get(c)) {
            if (c == '-') {
                neg = true;
                start = true;
            } else if (c >= '0' && c <= '9') {
