using namespace std;

class Reader {
    static const int BUFFER_SIZE = 1 << 16;
    FILE* in;
    char buffer[BUFFER_SIZE];
    int bufferPointer, bytesRead;

public:
    Reader() {
        in = stdin;
        bufferPointer = bytesRead = 0;
    }

    string readLine() {
        vector<char> buf(64);
        int cnt = 0;
        while (true) {
            int c = read();
            if (c == -1 || c == '\n') break;
            if (cnt < buf.size()) {
                buf[cnt++] = (char)c;
            } else {
                buf.push_back((char)c);
                cnt++;
            }
        }
        return string(buf.begin(), buf.begin() + cnt);
    }

    int nextInt() {
        int ret = 0;
        int c = read();
        while (isspace(c)) c = read();
        bool neg = (c == '-');
        if (neg) c = read();
        do {
            ret = ret * 10 + c - '0';
        } while ((c = read()) >= '0' && c <= '9');
        if (neg) return -ret;
        return ret;
    }

    long long nextLong() {
        long long ret = 0;
        int c = read();
        while (isspace(c)) c = read();
        bool neg = (c == '-');
        if (neg) c = read();
        do {
            ret = ret * 10 + c - '0';
        } while ((c = read()) >= '0' && c <= '9');
        if (neg) return -ret;
        return ret;
    }

    double nextDouble() {
        double ret = 0, div = 1;
        int c = read();
        while (isspace(c)) c = read();
        bool neg = (c == '-');
        if (neg) c = read();
        do {
            ret = ret * 10 + c - '0';
        } while ((c = read()) >= '0' && c <= '9');
        if (c == '.') {
            while ((c = read()) >= '0' && c <= '9') {
                ret += (c - '0') / (div *= 10);
            }
        }
        if (neg) return -ret;
        return ret;
    }

private:
    int read() {
        if (bufferPointer == bytesRead) {
            fillBuffer();
        }
        if (bytesRead == -1) return -1;
        return (unsigned char)buffer[bufferPointer++];
    }

    void fillBuffer() {
        bytesRead = fread(buffer, 1, BUFFER_SIZE, in);
        bufferPointer = 0;
        if (bytesRead == 0) bytesRead = -1;
    }
};

