            } else if (pod1 < pod2) {
                long long nextMass1 = getMass(pod2 - pod1);
                if (nextMass1 != 0) {
                    pod1 += nextMass1;
                } else {
                    break;
                }
            } else {
                isBalance = true;
                break;
            }
        }
        return isBalance;
    }

    long long getMass(long long mass) {
        long long result;
        int logBase = 0;
        if (weight > 1 && mass > 0) {
            logBase = (int)(log(mass) / log(weight));
        }

        mpz_class bi(weight);
        bi = pow(bi, logBase + 1);
        bi -= 1;
        bi /= (weight - 1);
        long long sumTotal = bi.get_ui();

        if (mass > sumTotal && !arr[logBase + 1]) {
            result = (long long)pow(weight, logBase + 1);
            arr[logBase + 1] = true;
        } else if (mass <= sumTotal && !arr[logBase]) {
            result = (long long)pow(weight, logBase);
            arr[logBase] = true;
        } else {
            result = 0;
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> weight >> itemMass;
    Main wb;
    if (wb.isBalanced())
        cout << "YES\n";
    else
        cout << "NO\n";
    return 0;
}

