using namespace std;

const long long MOD = 998244353;

long long x, y;

long long exp_mod(long long a, long long e) {
    if (e == 0) return 1;
    if (e == 1) return a % MOD;
    long long r = exp_mod(a, e >> 1);
    r = (r * r) % MOD;
    if (e & 1) r = (r * a) % MOD;
    return r;
}

long long gcdExt(long long a, long long b, long long &x, long long &y) {
    if (a == 0) {
        x = 0; y = 1;
        return b;
    }
    long long x1, y1;
    long long gcd = gcdExt(b % a, a, x1, y1);
    x = y1 - (b / a) * x1;
    y = x1;
    return gcd;
}

long long inv(long long a, long long b) {
    x = 0; y = 1;
    gcdExt(a, b, x, y);
    return (x % b + b) % b;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; long long k;
