#include <bits/stdc++.h>
using namespace std;

static int fmod = 998244353;
static int[] fact;
static int[] ifact;

int fmul(int a, int b) {
    return (int)((long long)a * b % fmod);
}

int fpow(int a, int b) {
    if (a == 0) return 0;
    int ans = 1;
    while (b > 0) {
        if (b & 1) ans = fmul(ans, a);
        a = fmul(a, a);
        b >>= 1;
    }
    return ans;
}

int ifact_func(int x) {
    if (ifact[x] > 0) {
        return ifact[x];
    } else {
        return ifact[x] = fpow(fact[x], fmod - 2);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k, ans = 0, mult = 1;
    long long kl;
    cin >> n;
    fact = new int[n + 1];
    ifact = new int[n + 1];
    fact[0] = fact[1] = 1;
    for (int i = 2; i <= n; ++i) {
        fact[i] = fmul(fact[i - 1], i);
    }
    cin >> kl;
    if (kl >= n) {
        cout << 0 << "\n";
        delete[] fact;
        delete[] ifact;
        return 0;
    }
    k = (int)kl;
    for (int i = 0; i <= n - k; ++i, mult = -mult) {
        int add = mult * fmul(fpow(n - k - i, n), fmul(fact[n - k], fmul(ifact_func(i), ifact_func(n - k - i))));
        while (add < 0) {
            add += fmod;
        }
        ans += add;
        if (ans >= fmod) {
            ans -= fmod;
        }
    }
    ans = fmul(fmul(ans, fact[n]), fmul(ifact_func(k), ifact_func(n - k)));
    if (k == 0) {
        cout << ans << "\n";
    } else {
        cout << fmul(ans, 2) << "\n";
    }
    delete[] fact;
    delete[] ifact;
    return 0;
}

