#include <bits/stdc++.h>
using namespace std;

class InputReader {
public:
    std::istream& in;
    std::string token;
    std::stringstream ss;

    InputReader(std::istream& input) : in(input) {}

    std::string nextLine() {
        std::string line;
        if (std::getline(in, line))
            return line;
        else
            return "";
    }

    std::string next() {
        while (!(ss >> token)) {
            std::string line = nextLine();
            if (line.empty()) return "";
            ss.clear();
            ss.str(line);
        }
        return token;
    }

    int nextInt() {
        return std::stoi(next());
    }

    long long nextLong() {
        return std::stoll(next());
    }

    double nextDouble() {
        return std::stod(next());
    }
};

class Task {
public:
    static const int mod = 998244353;
    std::vector<long long> fac, inv;

    long long powMod(long long a, long long b) {
        long long ans = 1, d = a % mod;
        while (b > 0) {
            if (b & 1) ans = ans * d % mod;
            b >>= 1;
            d = d * d % mod;
        }
        return ans;
    }

    void precomputeFactorials(int n) {
        fac.resize(n);
        inv.resize(n);
        fac[0] = 1;
        for (int i = 1; i < n; i++) {
            fac[i] = fac[i - 1] * i % mod;
        }
        inv[n - 1] = powMod(fac[n - 1], mod - 2);
        for (int i = n - 2; i >= 0; i--) {
            inv[i] = inv[i + 1] * (i + 1) % mod;
        }
    }

    long long getC(int n, int m) {
        if (m < 0 || m > n) return 0;
        return fac[n] * inv[m] % mod * inv[n - m] % mod;
    }

    void solve(int testNumber, InputReader& in, std::ostream& out) {
        int n = 200001;
        precomputeFactorials(n);
        n = in.nextInt();
        long long k = in.nextLong();
        if (k >= n) {
            out << 0 << "\n";
            return;
        }
        if (k == 0) {
            out << fac[n] << "\n";
            return;
        }
        int m = (int)(n - k);
        long long ans = 0;
        for (int i = 0; i <= m; i++) {
            long long c = getC(m, i);
            long long power = powMod(m - i, n);
            if (i % 2 == 0) {
                ans = (ans + c * power % mod) % mod;
            } else {
                ans = (ans - c * power % mod + mod) % mod;
            }
        }
        long long result = 2LL * fac[n] % mod * inv[n - m] % mod * ans % mod * inv[m] % mod;
        out << result << "\n";
    }
};

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    InputReader in(std::cin);
    Task solver;
    solver.solve(1, in, std::cout);
    return 0;
}

