    for (int i = 999998; i >= 0; i--) {
        factInvs[i] = mulMod(factInvs[i + 1], i + 1);
    }
}

long long nCk(int n, int k) {
    return mulMod(facts[n], mulMod(factInvs[k], factInvs[n - k]));
