class NumberTheory {
public:
    class Modulus {
    public:
        vector<long long> factorial;
        vector<long long> invFactorial;

        Modulus() {
            factorial.push_back(1LL);
            invFactorial.push_back(1LL);
        }

        virtual long long modulus() const = 0;

        long long fact(int n) {
            while ((int)factorial.size() <= n) {
                factorial.push_back(mult(factorial.back(), factorial.size()));
            }
            return factorial[n];
        }

        long long fInv(int n) {
            int lastKnown = (int)invFactorial.size() - 1;
            if (lastKnown < n) {
                vector<long long> fInvArr(n - lastKnown);
                fInvArr[0] = inv(fact(n));
                for (int i = 1; i < (int)fInvArr.size(); i++) {
                    fInvArr[i] = mult(fInvArr[i - 1], n - i + 1);
                }
                for (int i = (int)fInvArr.size() - 1; i >= 0; i--) {
                    invFactorial.push_back(fInvArr[i]);
                }
            }
            return invFactorial[n];
        }

        long long paritySign(long long k) const {
            return (k & 1) == 0 ? 1LL : modulus() - 1LL;
        }

        long long ncr(int n, int r) {
            assert(n >= 0);
            if (r < 0 || n < r)
                return 0;
            return mult(fact(n), mult(fInv(r), fInv(n - r)));
        }

        long long normalize(long long x) const {
            x %= modulus();
            if (x < 0)
                x += modulus();
            return x;
        }

        long long add(long long a, long long b) const {
            long long v = a + b;
            return v < modulus() ? v : v - modulus();
        }

        long long mult(long long a, long long b) const {
            return (a * b) % modulus();
        }

        long long mult(long long a, long long b, long long c) const {
            return mult(mult(a, b), c);
        }

        long long pow(long long x, int e) {
            if (e < 0) {
                x = inv(x);
                e = -e;
            }
            long long result = 1LL;
            long long base = x;
            while (e > 0) {
                if (e & 1) {
                    result = mult(result, base);
                }
                base = mult(base, base);
                e >>= 1;
            }
            return result;
        }

        long long inv(long long value) {
            long long g = modulus(), x = 0, y = 1;
            for (long long r = value; r != 0; ) {
                long long q = g / r;
                g %= r;

                long long temp = g;
                g = r;
                r = temp;

                temp = x;
                x = y - q * x;
                y = temp;
            }
            assert(g == 1);
            assert(y == modulus() || y == -modulus());
            return normalize(x);
        }
    };

    class Mod998 : public Modulus {
    public:
        long long modulus() const override {
            return 998244353LL;
        }
    };
};

struct EPlacingRooks {
    NumberTheory::Mod998 mod;

    void solve() {
        int n;
        long long k;
        cin >> n >> k;
        if (k == 0) {
            cout << mod.fact(n) << "\n";
            return;
        }
        if (k > n - 1) {
            cout << 0 << "\n";
            return;
        }
        int c = n - (int)k;
        long long answer = 0;
        for (int i = 1; i <= c; i++) {
            long long term = mod.mult(mod.paritySign(c - i), mod.ncr(c, i), mod.pow(i, n));
            answer = mod.add(answer, term);
        }
        answer = mod.mult(answer, 2LL, mod.ncr(n, c));
        cout << answer << "\n";
    }
};

