int n, m, maxm;
vector<vector<vector<int>>> dp;
vector<int> s;

int cal(int cur) {
    int res = 0;
    while (cur > 0) {
        res++;
        cur &= (cur - 1);
    }
    return res;
}

bool check(int a, int b, int c) {
    int res = (maxm - 1) & (b | (b << 1) | (b >> 1) | a | c);
    return res == maxm - 1;
}

