#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

long long min_ll(long long a, long long b) {
    return (a < b) ? a : b;
}

long long max_ll(long long a, long long b) {
    return (a > b) ? a : b;
}

void solve(int n, int mod) {
    vector<vector<long long>> inversions;
    inversions.push_back({1});

    vector<long long> last;
    vector<long long> next;
    for (int i = 1; i < n; i++) {
        last = inversions[i - 1];
        int size_next = i * (i + 1) / 2 + 1;
        next.assign(size_next, 0);

        for (int j = 0; j < size_next; j++) {
            long long e = 0;
            for (int k = max_ll(j, 0); k >= 0; k--) {
                if (j - k < (int)last.size()) {
                    e += last[j - k];
                    e %= mod;
                }
            }
            next[j] = e;
        }
        inversions.push_back(next);
    }

    vector<long long> perms(n, 0);
    perms[0] = 0;

    for (int i = 1; i < n; i++) {
        long long c = (perms[i - 1] * (i + 1)) % mod;
        vector<long long>& inv = inversions[i - 1];

        for (int j = 0; j < (int)inv.size(); j++) {
            for (int k = j + 2; k < (int)inv.size(); k++) {
                long long m = min_ll(k - j, i + 1);
                long long term = ((inv[j] * inv[k]) % mod) * ((m - 1) * (2 * i - (m - 2)) / 2);
                term %= mod;
                c = (c + term) % mod;
            }
        }
        perms[i] = c;
    }

    cout << perms[n - 1] << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;
    solve(n, mod);
