    static void intersectAt(const Circle& a, const Circle& b, std::set<Point>& set) {
        if (!isIntersect(a, b)) {
            return;
        }
        Line line(a.center, b.center);
        double d = distance(a.center, b.center);
        double middleDistance = (d * d - b.r * b.r + a.r * a.r) / (2 * d);
        Point middle = a.center.moveAlongLine(line.asVector(), middleDistance);
        Point alpha = line.asVector().getAlpha();
        double height = std::sqrt(a.r * a.r - middleDistance * middleDistance);
        Point first = middle.moveAlongVector(alpha, height);
        Point second = middle.moveAlongVector(alpha, -height);
        set.insert(first);
        if (!(second == first)) {
            set.insert(second);
        }
    }
};

int main() {
    int n;
    std::cin >> n;
    std::vector<Circle> circles;
    for (int i = 0; i < n; ++i) {
        int x, y, r;
        std::cin >> x >> y >> r;
        circles.emplace_back(x, y, r);
    }

    if (n == 3 && !Circle::isIntersect(circles[0], circles[1])) {
        int sum = 4;
        if (Circle::isIntersect2(circles[0], circles[2])) {
            sum++;
        }
        if (Circle::isIntersect2(circles[1], circles[2])) {
            sum++;
        }
        std::cout << sum << "\n";
        return 0;
    }

    int total = 1;
    std::set<Point> setPoints;
    for (int i = 0; i < n; ++i) {
        setPoints.clear();
        total++;
        for (int j = 0; j < i; ++j) {
            Circle::intersectAt(circles[i], circles[j], setPoints);
        }
        if ((int)setPoints.size() >= 2) {
            total += (int)setPoints.size() - 1;
        }
    }
    std::cout << total << "\n";

    return 0;
}

