    cin >> n;
    string s;
    cin >> s;

    int nk = 0, nv = 0, no = 0;
    vector<int> kpos(n), vpos(n), opos(n);
    vector<int> snk(n + 1, 0), snv(n + 1, 0), sno(n + 1, 0);

    for (int i = 0; i < n; ++i) {
        char ch = s[i];
        if (ch == 'V') {
            vpos[nv++] = i;
        } else if (ch == 'K') {
            kpos[nk++] = i;
        } else {
            opos[no++] = i;
        }
        snk[i + 1] = nk;
        snv[i + 1] = nv;
        sno[i + 1] = no;
    }

    const int INF = 1000000000;
    vector<vector<vector<vector<int>>>> best(2,
        vector<vector<vector<int>>>(nk + 1,
            vector<vector<int>>(nv + 1,
                vector<int>(no + 1, INF)
            )
        )
    );

    best[0][0][0][0] = 0;

    for (int k = 0; k <= nk; ++k) {
        for (int v = 0; v <= nv; ++v) {
            for (int o = 0; o <= no; ++o) {
                for (int hv = 0; hv < 2; ++hv) {
