        cin >> n;
        string s;
        cin >> s;
        cout << solve(s) << "\n";
    }

    int stupid(const string& s) {
        std::queue<std::string> q;
        std::unordered_map<std::string, int> dist;
        q.push(s);
        dist[s] = 0;
        while (!q.empty()) {
            std::string st = q.front();
            q.pop();
            int cur = dist[st];
            if (st.find("VK") == std::string::npos) {
                return cur;
            }
            for (size_t pos = 0; pos + 1 < st.size(); ++pos) {
                std::string next = st;
                std::swap(next[pos], next[pos + 1]);
                if (dist.find(next) == dist.end()) {
                    dist[next] = cur + 1;
                    q.push(next);
                }
            }
        }
        return 0;
    }

    int solve(const std::string& s) {
        std::vector<int> vPos, kPos, otherPos;
        for (size_t i = 0; i < s.size(); ++i) {
            if (s[i] == 'V') vPos.push_back(i);
            else if (s[i] == 'K') kPos.push_back(i);
            else otherPos.push_back(i);
        }

        int VSize = vPos.size();
        int KSize = kPos.size();
        int OSize = otherPos.size();

        int dp[2][101][101][101];
        for (int last = 0; last < 2; ++last) {
            for (int V = 0; V <= VSize; ++V) {
                for (int K = 0; K <= KSize; ++K) {
                    for (int O = 0; O <= OSize; ++O) {
                        dp[last][V][K][O] = INF;
                    }
                }
            }
        }
        dp[0][0][0][0] = 0;

        for (int V = 0; V <= VSize; ++V) {
            for (int K = 0; K <= KSize; ++K) {
                for (int O = 0; O <= OSize; ++O) {
                    for (int last = 0; last < 2; ++last) {
                        int cur = dp[last][V][K][O];
                        if (cur == INF) continue;
                        if (V < VSize) {
                            int cost = count(vPos[V], K, kPos) + count(vPos[V], O, otherPos);
                            dp[1][V + 1][K][O] = std::min(dp[1][V + 1][K][O], cur + cost);
                        }
                        if (K < KSize && last == 0) {
                            int cost = count(kPos[K], V, vPos) + count(kPos[K], O, otherPos);
                            dp[0][V][K + 1][O] = std::min(dp[0][V][K + 1][O], cur + cost);
                        }
                        if (O < OSize) {
                            int cost = count(otherPos[O], V, vPos) + count(otherPos[O], K, kPos);
                            dp[0][V][K][O + 1] = std::min(dp[0][V][K][O + 1], cur + cost);
                        }
                    }
                }
            }
        }
        return std::min(dp[0][VSize][KSize][OSize], dp[1][VSize][KSize][OSize]);
    }

private:
    int count(int position, int start, const std::vector<int>& positions) {
        int ans = 0;
        for (size_t i = start; i < positions.size(); ++i) {
            if (positions[i] < position) {
                ans++;
            }
        }
        return ans;
    }
};

