        return a;
    }

    long long timeBegin, timeEnd;

    void time() {
        timeEnd = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now().time_since_epoch()
        ).count();
        std::cerr << "Time = " << (timeEnd - timeBegin) << "\n";
    }

    int count(const std::vector<char>& s, char target, int v, int k, int x) {
        int answer = 0;
        for (char c : s) {
            if (c == 'V') {
                v--;
                if (v == 0 && target == 'V') return answer;
                if (v < 0) answer++;
            }
            if (c == 'K') {
                k--;
                if (k == 0 && target == 'K') return answer;
                if (k < 0) answer++;
            }
            if (c == 'X') {
                x--;
                if (x == 0 && target == 'X') return answer;
                if (x < 0) answer++;
            }
        }
        throw std::runtime_error("Count function failed");
    }

    void solve() {
        int n = readInt();
        std::string s_str = readString();
        std::vector<char> s(s_str.begin(), s_str.end());
        int vcnt = 0, kcnt = 0, xcnt = 0;
        for (int i = 0; i < s.size(); i++) {
            if (s[i] == 'V') {
                vcnt++;
                continue;
            }
            if (s[i] == 'K') {
                kcnt++;
                continue;
            }
            xcnt++;
            s[i] = 'X';
        }
        const int INF = 10000000;
        std::vector<std::vector<std::vector<std::vector<int>>>> dp(
            vcnt + 1,
            std::vector<std::vector<std::vector<int>>>(
                kcnt + 1,
                std::vector<std::vector<int>>(
                    xcnt + 1,
                    std::vector<int>(3, INF)
                )
            )
        );
        for (int now = 0; now < 3; now++) {
            dp[0][0][0][now] = 0;
        }

        for (int v = 0; v <= vcnt; v++) {
            for (int k = 0; k <= kcnt; k++) {
                for (int x = 0; x <= xcnt; x++) {
                    int rv = (v + 1 <= vcnt) ? count(s, 'V', v + 1, k, x) : 0;
                    int rk = (k + 1 <= kcnt) ? count(s, 'K', v, k + 1, x) : 0;
                    int rx = (x + 1 <= xcnt) ? count(s, 'X', v, k, x + 1) : 0;

                    for (int now_state = 0; now_state < 3; now_state++) {
                        int current_cost = dp[v][k][x][now_state];
                        if (current_cost == INF) continue;
                        if (v + 1 <= vcnt) {
                            dp[v + 1][k][x][0] = std::min(dp[v + 1][k][x][0], current_cost + rv);
                        }
                        if (now_state != 0 && k + 1 <= kcnt) {
                            dp[v][k + 1][x][1] = std::min(dp[v][k + 1][x][1], current_cost + rk);
                        }
                        if (x + 1 <= xcnt) {
                            dp[v][k][x + 1][2] = std::min(dp[v][k][x + 1][x][2], current_cost + rx);
                        }
                    }
                }
            }
        }

        int res = INF;
        for (int i = 0; i < 3; i++) {
            res = std::min(res, dp[vcnt][kcnt][xcnt][i]);
        }
        (*out) << res << "\n";
    }

    void run() {
        timeBegin = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now().time_since_epoch()
        ).count();
        init();
        try {
            solve();
        } catch (...) {
            std::cerr << "Exception occurred\n";
            std::exit(-1);
        }
        time();
    }
};

int main() {
    J solver;
    solver.run();
    return 0;
}

