long power(long x, long y, long m) {
    long result = 1;
    long base = x % m;
    while (y > 0) {
        if (y % 2 == 1) {
            result = (result * base) % m;
        }
        base = (base * base) % m;
        y /= 2;
    }
    return result;
}

