    public static void main(String[] args) throws IOException {
        Reader in = new Reader();
        PrintWriter out = new PrintWriter(System.out);
        
        String s = in.next();
        int end = 1;
        for (int i = 0; i < s.length(); i++) {
           end *= 10;
        }
        int res = 0;
        for (int i = 0; i < end; i += 25) {
            if (match(s, i)) {
                res++;
            }
        }
        out.println(res);
        
        out.close();
    }
    public static boolean match(String s, int n) {
        int x = -1;
        for (int i = s.length() - 1; i >= 0; i--) {
            int d = n % 10;
            if (s.charAt(i) == 'X') {
                if (x >= 0 && x != d) {
                    return false;
                }
                x = d;
            } else if (s.charAt(i) != '_') {
                if (s.charAt(i) - '0' != d) {
                    return false;
                }
            }
            if (s.length() > 1 && i == 0 && d == 0) {
                return false;
            }
            n /= 10;
        }
        return true;
    }
