    int res = 0;
    for (int i = 0; i < k; i++) {
        res = (res << 1) | (n & 1);
        n >>= 1;
    }
    return res;
}

long long modInv(int a) {
    long long res = 1, base = a, p = MOD - 2;
    while (p > 0) {
        if (p & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        p >>= 1;
    }
    return res;
}

