		while (k-- > 0) {
			int d = Integer.parseInt(st.nextToken());
			aa[d] = 1;
		}
		ntt(aa, n_, false);
		for (int i = 0; i < n_; i++)
			aa[i] = (int) power(aa[i], n);
		ntt(aa, n_, true);
		long v = power(n_, MD - 2);
		for (int i = 0; i < n_; i++) {
			aa[i] = (int) (aa[i] * v % MD);
			if (aa[i] < 0)
				aa[i] += MD;
		}
		long ans = 0;
		for (int i = 0; i <= n * 9; i++) {
			long a = aa[i];
			ans = (ans + a * a) % MD;
		}
		System.out.println(ans);
