        //$
        // To use: FFT both, product, iFFT (n is next power of 2)
        static long[] fftOr(long[] arr, int n, boolean invert) {
            long[] ans = Arrays.copyOf(arr, n);
            for (int b = 1; b < n; b <<= 1)
                for (int i = 0; i < n; i++) {
                    if ((i & b) != 0) continue;
                    ans[i + b] += invert ? -ans[i] : ans[i];
