		int len = 1, nn = n / 2;
		while(len < (9 * nn + 1)) len <<= 1;
		long[] a = new long[len];
		long[] b = new long[len];

		a[0] = 1;
		for(int i = 0; i < m; i++) {
			int x = in.nextInt();
			b[x] = 1;
		}

		NTT(a, len, 1);
		NTT(b, len, 1);

		for(int i = 0; i < len; i++) {
			if(a[i] != 0 && b[i] != 0) {
				a[i] = a[i] * qpow(b[i], nn) % mod;
			} else a[i] = 0;
		}

		NTT(a, len, -1);

		long ans = 0;
		for(int i = 0; i < len; i++)
