    int64_t base = a % MOD;
    while (p > 0) {
        if (p & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        p >>= 1;
    }
    return result;
}

int64_t modInv(int64_t a) {
    return modPow(a, MOD - 2);
}

vector<int64_t> calcRoots(int k, bool inverse) {
    int64_t root = modPow(ROOT, (int64_t)1 << (twoPow - k));
    if (inverse) {
        root = modInv(root);
    }
    vector<int64_t> roots(k);
    if (k > 0) {
        roots[k - 1] = root;
    }
    for (int i = k - 1; i > 0; i--) {
        roots[i - 1] = (roots[i] * roots[i]) % MOD;
    }
    return roots;
}

vector<int64_t> reorderArray(const vector<int64_t>& a, int k) {
    vector<int64_t> ans(a.size());
    for (size_t i = 0; i < a.size(); i++) {
        ans[bitReverse(i, k)] = a[i];
    }
    return ans;
}

vector<int64_t> numberTheoreticTransform(vector<int64_t> coef, int k, bool inverse) {
    coef = reorderArray(coef, k);
    vector<int64_t> roots = calcRoots(k, inverse);
    for (int s = 0; s < k; s++) {
        int len = 1 << s;
        for (int st = 0; st < (int)coef.size(); st += 2 * len) {
            int64_t curRoot = 1;
            for (int j = st; j < st + len; j++) {
                int64_t t = (curRoot * coef[j + len]) % MOD;
                int64_t u = coef[j];
                coef[j] = (u + t) % MOD;
                coef[j + len] = (u - t + MOD) % MOD;
                curRoot = (roots[s] * curRoot) % MOD;
            }
        }
    }
    return coef;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n_input, m;
    cin >> n_input >> m;
    int n = n_input / 2;
    vector<int> nums(m);
    int maxVal = 0;
    for (int i = 0; i < m; i++) {
        cin >> nums[i];
        maxVal = max(maxVal, nums[i]);
    }
    int min_size = n * maxVal + 1;
    int size = 1;
    int k = 0;
    while (size < min_size) {
        size <<= 1;
        k++;
    }
    vector<int64_t> a(size, 0);
    for (int num : nums) {
        a[num] = 1;
    }
    a = numberTheoreticTransform(a, k, false);
    for (size_t i = 0; i < a.size(); i++) {
        a[i] = modPow(a[i], n);
    }
    a = numberTheoreticTransform(a, k, true);
    int64_t ans = 0;
    for (size_t i = 0; i < a.size(); i++) {
        ans = (ans + a[i] * a[i]) % MOD;
    }
    int64_t multiplier = modInv(size);
    int64_t result = ((ans * multiplier) % MOD * multiplier) % MOD;
    cout << result << "\n";
    return 0;
}

