                        tl = tm + 1;
                        a = 2 * a + 1;
                    }
                }
                tree[a] = val;
                a >>= 1;
                while (a > 0) {
                    tree[a] = Math.min(tree[2 * a], tree[2 * a + 1]);
                    a >>= 1;
                }
            }

            int getVal(int i) {
                if (i < 0) {
                    return MAX;
                }
                return arr[i];
            }

        }

    }

