        upper = ones[(int)(numOfDigits - 1)];
    } else if (n > lower) {
        upper = ones[(int)(numOfDigits + 1)];
    } else {
        return numOfDigits;
    }
    long long resLower = decompose(n % lower) + (n / lower) * getNumOfDigits(lower);
    long long resUpper = LLONG_MAX;
    if (upper - n < n) {
        resUpper = decompose(upper - n) + getNumOfDigits(upper);
    }
    return std::min(resLower, resUpper);
}

int main() {
    // Initialize reader (not necessary in C++, but kept for structure)
    // Read input
    long long n = Reader::nextLong();
    long long res = decompose(n);
    cout << res << "\n";
    return 0;
}

