#include <bits/stdc++.h>
using namespace std;

class TaskC {
public:
    void solve() {
        long long result = f(readLong());
        cout << result << "\n";
    }

private:
    long long f(long long n) {
        static long long pow[16];
        static bool initialized = false;
        if (!initialized) {
            pow[0] = 1LL;
            for (int i = 1; i < 16; i++) {
                pow[i] = 10LL * pow[i - 1] + 1LL;
            }
            initialized = true;
        }
        if (n <= 1LL) return n;
        int pos = 15;
        while (pos >= 0 && pow[pos] >= n) pos--;
        pos++;
        long long m1 = 0LL, m2 = pow[pos];
        int x1 = 0, x2 = pos + 1;
        while (m1 + pow[pos - 1] <= n) {
            m1 += pow[pos - 1];
            x1 += pos;
        }
        while (m2 - pow[pos - 1] >= n) {
            m2 -= pow[pos - 1];
            x2 += pos;
        }
        x1 += f(n - m1);
        x2 += f(m2 - n);
        return min(x1, x2);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    TaskC solver;
    solver.solve();
    return 0;
}

long long readLong() {
    long long x; cin >> x; return x;
}

