        d[0] = 0;
        for (int i = 0; i < N - 1; i++) {
            for (int j = 0; j < N; j++) {
                for (auto &e : ja[j]) {
                    if (e.flow == 0) continue;
                    if (d[j] + e.cost < d[e.u]) {
                        d[e.u] = d[j] + e.cost;
                    }
                }
            }
