            for (int i = 0; i < (int)ja[u].size(); i++) {
                auto &e = ja[u][i];
                if (e.flow == 0) continue;
                int cdist = dist[u] + e.cost;
                if (cdist < dist[e.u]) {
                    if (visit[e.u] == 0) {
                        node[front] = e.u;
                        if (++front == N) front = 0;
                    } else if (visit[e.u] == 2) {
                        if (--back == -1) back += N;
                        node[back] = e.u;
                    }
                    visit[e.u] = 1;
