#include <bits/stdc++.h>
using namespace std;

class CF1187G {
public:
    CF1187G() {}
    static const int INF = 0x3f3f3f3f;
    vector<vector<int>> aa_;
    vector<int> pi, dd, bb;
    vector<int> uu, vv, uv, cost, cc;
    vector<int> qq;
    vector<bool> iq;
    int n_, m_;
    int m, nq, head, cnt;
    int n, k, c, d;
    vector<int> ii;
    vector<vector<int>> aa;
    int t;

    void init() {
        aa_.assign(n_, vector<int>());
        pi.assign(n_, INF);
        dd.assign(n_, 0);
        bb.assign(n_, 0);
        qq.assign(nq, 0);
        iq.assign(n_, false);
        uu.assign(m, 0);
        vv.assign(m, 0);
        uv.assign(m, 0);
        cost.assign(m, 0);
        cc.assign(m * 2, 0);
        m = 0;
    }

    void link(int u, int v, int cap, int cos) {
        int h = m++;
        uu[h] = u;
        vv[h] = v;
        uv[h] = u ^ v;
        cost[h] = cos;
        cc[h << 1] = cap;
        aa_[u].push_back(h << 1);
        aa_[v].push_back((h << 1) ^ 1);
    }

    void enqueue(int v) {
        if (iq[v]) return;
        if (head + cnt == nq) {
            if (cnt * 2 <= nq) {
                // do nothing, as vector handles resizing
            } else {
                nq <<= 1;
                qq.resize(nq);
            }
            head = 0;
        }
        qq[head + cnt] = v;
        cnt++;
        iq[v] = true;
    }

    int dequeue() {
        int u = qq[head++];
        cnt--;
        iq[u] = false;
        return u;
    }

    bool spfa(int s, int t) {
        std::fill(pi.begin(), pi.end(), INF);
        pi[s] = 0;
        head = 0;
        cnt = 0;
        enqueue(s);
        while (cnt > 0) {
            int u = dequeue();
            int d = dd[u] + 1;
            for (int h_ : aa_[u]) {
                if (cc[h_] > 0) {
                    int h = h_ >> 1;
                    int p = pi[u] + ((h_ & 1) == 0 ? cost[h] : -cost[h]);
                    int v = u ^ uv[h];
                    if (pi[v] > p || (pi[v] == p && dd[v] > d)) {
                        pi[v] = p;
                        dd[v] = d;
                        bb[v] = h_;
                        enqueue(v);
                    }
                }
            }
        }
        return pi[t] != INF;
    }

    void push(int s, int t) {
        int c = INF;
        for (int u = t, h_, h; u != s; u ^= uv[h]) {
            h = (h_ = bb[u]) >> 1;
            c = std::min(c, cc[h_]);
        }
        for (int u = t, h_, h; u != s; u ^= uv[h]) {
            h = (h_ = bb[u]) >> 1;
            cc[h_] -= c;
            cc[h_ ^ 1] += c;
        }
    }

    void push1(int s, int t) {
        for (int u = t, h_, h; u != s; u ^= uv[h]) {
            h = (h_ = bb[u]) >> 1;
            cc[h_]--;
            cc[h_ ^ 1]++;
        }
    }

    int edmonds_karp(int s, int t) {
        while (spfa(s, t))
            push1(s, t);
        int c = 0;
        for (int h = 0; h < m; h++)
            c += cost[h] * cc[(h << 1) ^ 1];
        return c;
    }

    void main() {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);
        cin >> n >> m >> k >> c >> d;
        ii.resize(k);
        for (int h = 0; h < k; h++) {
            cin >> ii[h];
            ii[h]--;
        }
        aa.assign(n, vector<int>());
        for (int h = 0; h < m; h++) {
            int i, j;
            cin >> i >> j;
            i--; j--;
            aa[i].push_back(j);
            aa[j].push_back(i);
        }
        t = n + k + 1;
        n_ = n * t + 1;
        m_ = k + (m * 2 * k + n) * (t - 1);
        init();
        for (int i = 0; i < n; i++) {
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s;
                for (int j : aa[i]) {
                    int v = j * t + s + 1;
                    for (int x = 1; x <= k; x++) {
                        link(u, v, 1, c + (x * 2 - 1) * d);
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s;
                int v = u + 1;
                link(u, v, k, i == 0 ? 0 : c);
            }
        }
        for (int h = 0; h < k; h++) {
            link(n_ - 1, ii[h] * t + 0, 1, 0);
        }
        cout << edmonds_karp(n_ - 1, 0 * t + t - 1) << "\n";
    }
};

