        int sink = snk->index;
        long long flow = 0;
        long long cost = 0;
        std::vector<long long> potential(n, 0);
        while (true) {
            std::vector<Edge*> parent(n, nullptr);
            std::vector<long long> dist(n, EdmondsKarp::INF);
            dist[source] = 0;
            typedef std::pair<long long, int> PLI;
            std::priority_queue<PLI, std::vector<PLI>, std::greater<PLI>> que;
            que.emplace(0, source);
            while (!que.empty()) {
