    int mask = scale - 1;
    int size = 0;
    static const long long NG = 0;

    LongHashCounterL() {
        allocated.assign(scale, NG);
        keys.assign(scale, 0);
    }

    bool containsKey(long long x) {
        int pos = h(x) & mask;
        while (allocated[pos] != NG) {
            if (x == keys[pos]) return true;
            pos = (pos + 1) & mask;
        }
        return false;
    }

    long long get(long long x) {
        int pos = h(x) & mask;
        while (allocated[pos] != NG) {
            if (x == keys[pos]) return allocated[pos];
            pos = (pos + 1) & mask;
        }
        return NG;
    }

    long long put(long long x, long long v) {
        int pos = h(x) & mask;
        while (allocated[pos] != NG) {
            if (x == keys[pos]) {
                long long oldval = allocated[pos];
                allocated[pos] = v;
                return oldval;
            }
            pos = (pos + 1) & mask;
        }
        if (size == rscale) resizeAndPut(x, v);
        else {
            keys[pos] = x;
            allocated[pos] = v;
        }
        size++;
        return 0;
    }

