        if (size == rscale) resizeAndPut(x, v);
        else {
            keys[pos] = x;
            allocated[pos] = v;
        }
        size++;
        return v;
    }

    bool remove(long long x) {
        int pos = h(x) & mask;
        while (allocated[pos] != NG) {
            if (x == keys[pos]) {
                size--;
                int last = pos;
                pos = (pos + 1) & mask;
                while (allocated[pos] != NG) {
                    int lh = h(keys[pos]) & mask;
                    if ((lh <= last && last < pos) || (pos < lh && lh <= last) || (last < pos && pos < lh)) {
                        keys[last] = keys[pos];
                        allocated[last] = allocated[pos];
                        last = pos;
                    }
                    pos = (pos + 1) & mask;
                }
                keys[last] = 0;
                allocated[last] = NG;
