        long long ret = 0;
        for (int i = A; i < C; i++) {
            long long xi = x / primes[i];
            int B = (int)pi(sqrt_ll(xi));
            for (int j = i; j < B; j++) {
                ret += pi(xi / primes[j]) - j;
            }
        }
        return ret;
    }

    MeisselLehmer2(long long n) {
