        long long plus = ml.pi(n / primes[i]) - (i + 1);
        if (plus <= 0) break;
        ans += plus;
    }
    for (int p : primes) {
        if ((long long)p * p * p <= n) {
            ans++;
        } else {
            break;
        }
    }
    cout << ans << "\n";

    cin.rdbuf(cinbuf);
    return 0;
}

