        }
        ret -= (long long)(B - A) * (B + A - 1) / 2;
        return ret;
    }

    long long P3(long long x, int A) {
        int C = (int)pi(cbrt_ll(x));
        long long ret = 0;
        for (int i = A; i < C; i++) {
