    int FP[8] = { 2, 3, 5, 7, 11, 13, 17, 19 };
    int M = 8;
    int B = 100;

    long long sqrt_ll(long long n) {
        long long i = std::max((long long)0, (long long)std::sqrt((long double)n) - 2);
        while (i * i <= n) i++;
        return i - 1;
    }

    long long cbrt_ll(long long n) {
        long long i = std::max((long long)0, (long long)std::cbrt((long double)n) - 2);
        while (i * i * i <= n) i++;
        return i - 1;
    }

    long long pi(long long x) {
