            cumps[i].resize(len + 1);
            for (int j = 0; j < len; j++) {
                cumps[i][j + 1] = cumps[i][j] + (c[j] ? 1 : 0);
            }
            FP[i] = len;
            b = c;
        }
    }

    long long pi(long long x) {
        if (x <= cachelimit) {
            int ix = (int)x;
            return xcums[ix >> 6] + __builtin_popcountll(isp[ix >> 6] << (~ix));
        }
        if (picache.containsKey(x)) return picache.get(x);
        int A = (int)pi(sqrt_ll(sqrt_ll(x)));
