public class CF1153F {
	static final int MD = 998244353;
	static int[][] ch;
	static void init(int n) {
		ch = new int[1 + n][1 + n];
		ch[0][0] = 1;
		for (int i = 1; i <= n; i++) {
			ch[i][0] = 1;
			for (int j = 1; j <= i; j++)
				ch[i][j] = (ch[i - 1][j] + ch[i - 1][j - 1]) % MD;
		}
	}
	static long power(int a, int k) {
		if (k == 0)
			return 1;
		long p = power(a, k / 2);
		p = p * p % MD;
		if (k % 2 == 1)
			p = p * a % MD;
		return p;
	}
