#include <bits/stdc++.h>
using namespace std;

const int MD = 998244353;
int** ch;

void init(int n) {
    ch = new int*[n + 1];
    for (int i = 0; i <= n; i++) {
        ch[i] = new int[n + 1]();
    }
    ch[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        ch[i][0] = 1;
        for (int j = 1; j <= i; j++)
            ch[i][j] = (ch[i - 1][j] + ch[i - 1][j - 1]) % MD;
    }
}

long long power(long long a, int k) {
    long long res = 1;
    long long base = a % MD;
    while (k > 0) {
        if (k & 1) res = res * base % MD;
        base = base * base % MD;
        k >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k, l;
    cin >> n >> k >> l;
    init(n);
    vector<long long> pp(n + n + 1, 0);
    vector<long long> qq(n + n + 1, 0);
    pp[n] = power(2, n);
    for (int i = 0; i < n; i++) {
        for (int j = n + n; j > 0; j--) {
            pp[j] = (pp[j] - pp[j - 1]) % MD;
        }
    }
    vector<long long> aa(n + n + 1, 0);
    for (int j = 0; j <= n + n; j++) {
        aa[j] = pp[j];
    }
    long long inv2 = (MD + 1) / 2;
    for (int i = 1; i <= n - k; i++) {
        // qq := pp / p, where p = 2x (1 - x)
        // divide by 2x
        for (int j = 0; j < n + n; j++) {
            qq[j] = pp[j + 1] * inv2 % MD;
        }
        qq[n + n] = 0;
        // divide by 1 - x is multiply by 1 + x + x^2 + x^3 + ...
        for (int j = 1; j <= n + n; j++) {
            qq[j] = (qq[j] + qq[j - 1]) % MD;
        }
        // pp := qq - pp
        for (int j = 0; j <= n + n; j++) {
            pp[j] = (qq[j] - pp[j]) % MD;
        }
        long long a = ch[n][i];
        for (int j = 0; j <= n + n; j++) {
