#include <bits/stdc++.h>
using namespace std;

long long mod = 998244353;

vector<vector<long long>> enumFIF(int n, long long mod) {
    vector<long long> f(n + 1), invf(n + 1);
    f[0] = 1;
    for (int i = 1; i <= n; i++) {
        f[i] = f[i - 1] * i % mod;
    }
    long long a = f[n], b = mod, p = 1, q = 0;
    while (b > 0) {
        long long c = a / b, d = a;
        a = b;
        b = d % b;
        long long temp = p;
        p = q;
        q = temp - c * q;
    }
    invf[n] = p < 0 ? p + mod : p;
    for (int i = n - 1; i >= 0; i--) {
        invf[i] = invf[i + 1] * (i + 1) % mod;
    }
    return {f, invf};
}

long long C(int n, int r, const vector<long long>& f, const vector<long long>& invf) {
    if (n < 0 || r < 0 || r > n) return 0;
    return f[n] * invf[r] % mod * invf[n - r] % mod;
}

long long powLL(long long a, long long n, long long m) {
    long long ret = 1;
    while (n > 0) {
        if (n & 1) ret = ret * a % m;
        a = a * a % m;
        n >>= 1;
    }
    return ret;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, K, L;
    cin >> n >> K >> L;
    int maxN = 10000;
    auto fif = enumFIF(maxN, mod);
    vector<long long> muls(n + 1, 0);
    for (int i = K; i <= n; i++) {
        long long m = C(n, i, fif[0], fif[1]);
        for (int j = i; j <= n; j++) {
            long long sign = ((j - i) % 2 == 0) ? 1 : -1;
            long long val = m * C(n - i, n - j, fif[0], fif[1]) % mod * sign;
            muls[j] = (muls[j] + val) % mod;
