using namespace std;

const long long MOD = 998244353;

long long extended_gcd(long long a, long long b, long long &x, long long &y) {
    if (a == 0) {
        x = 0; y = 1;
        return b;
    }
    long long x1, y1;
    long long gcd = extended_gcd(b % a, a, x1, y1);
    x = y1 - (b / a) * x1;
    y = x1;
    return gcd;
}

long long modInverse(long long a, long long mod) {
    long long x, y;
    long long g = extended_gcd(a, mod, x, y);
    if (g != 1) {
        return 0;
    } else {
        return (x % mod + mod) % mod;
    }
}

long long modFraction(long long a, long long b, long long mod) {
    long long invB = modInverse(b, mod);
    if (invB == 0) {
        return -1;
    } else {
        return (invB * a) % mod;
    }
}

long long modLong(long long a, long long m) {
    long long res = a % m;
    if (res < 0) res += m;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long N, M;
    int K;
    cin >> N >> M >> K;

    long long mod = modFraction(1, M, MOD);
    vector<long long> expect(K + 1, 0);
    vector<long long> poly(K + 1, 0);
    expect[0] = 1;
    poly[0] = 1;
    long long curExpect = 1;

    for (int k = 1; k <= K; ++k) {
        curExpect = (curExpect * (N - (k - 1))) % MOD;
        long long temp = modFraction(curExpect, 1, MOD);
        curExpect = temp;

        for (int i = k; i >= 0; --i) {
            long long val = 0;
            if (i > 0) val += poly[i - 1];
            val -= (k - 1) * poly[i];
            poly[i] = modLong(val, MOD);
        }

        expect[k] = curExpect;
        for (int i = k - 1; i >= 0; --i) {
            long long sub = (poly[i] * expect[i]) % MOD;
            expect[k] = modLong(expect[k] - sub, MOD);
        }
    }

    cout << expect[K] << "\n";

    return 0;
}

