using namespace std;

class Task {
public:
    int mod = 998244353;

    int add(int a, int b) {
        int c = a + b;
        if (c >= mod) return c - mod;
        if (c < 0) return c + mod;
        return c;
    }

    int mult(int a, int b) {
        return (int)((long long)a * b % mod);
    }

    int mult(int a, int b, int c) {
        return mult(mult(a, b), c);
    }

    int mult(const vector<int>& x) {
        int r = 1;
        for (int y : x) {
            r = mult(r, y);
        }
        return r;
    }

    vector<vector<int>> stirling;

    void pre() {
        int size = 5001;
        stirling.assign(size, vector<int>(size, 0));
        for (int i = 0; i < size; i++) {
            stirling[i][0] = 0;
            stirling[0][1] = 0;
        }
        for (int i = 0; i < size; i++) {
            stirling[i][i] = 1;
        }
        for (int i = 2; i < size; i++) {
            for (int j = 1; j < i; j++) {
                stirling[i][j] = add(mult(stirling[i - 1][j], i - 1), stirling[i - 1][j - 1]);
            }
        }
    }

    void solve(istream& in, ostream& out) {
        pre();
        int n, m, k;
        in >> n >> m >> k;
        int invm = 0;
        {
            // Compute modular inverse of m using Fermat's little theorem
            // since mod is prime
            long long base = m;
            long long exponent = mod - 2;
            long long result = 1;
            long long cur = base % mod;
            while (exponent > 0) {
                if (exponent & 1) result = (result * cur) % mod;
                cur = (cur * cur) % mod;
                exponent >>= 1;
            }
            invm = (int)result;
        }
        vector<int> pVal(k + 1, 0);
        pVal[0] = 1;
        int md = n;
        int prp = 1;
        for (int i = 1; i <= k; i++) {
            prp = mult(prp, md, invm);
            md = add(md, -1);
            int sub = prp;
            for (int j = i - 1; j >= 1; j--) {
                int sign = ((i - j) % 2 == 1) ? 1 : -1;
                int val = add(0, -pVal[j]);
                sub = add(sub, mult(stirling[i][j], sign == 1 ? pVal[j] : val));
            }
            pVal[i] = sub;
        }
        out << pVal[k] << "\n";
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    Task t;
    t.solve(cin, cout);
    return 0;
}

