    static class GTakeMetro {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt(), m = in.nextInt();
            int s = in.nextInt() - 1;
            long t = in.nextLong();
            while (t % n != 0) {
                if (s < m) {
                    s = (int) ((s + t) % n);
                } else {
                    s = (int) ((s - t) % n);
                    if (s < 0) s += n;
                }
                t--;
            }
            t /= n;
            int[] seen = new int[n];
            Arrays.fill(seen, -1);
            seen[s] = 0;
            int count = 0;
            while (t-- > 0) {
                count++;
                for (int i = n - 1; i >= 1; i--) {
                    if (s < m) {
                        s = (s + i) % n;
                    } else {
                        s = (s - i + n) % n;
                    }
                }
                if (seen[s] != -1) {
                    t %= (count - seen[s]);
                }
                seen[s] = count;
            }
            out.println(s + 1);
        }

    }

