    static class GTakeMetro {
        int n;
        int m;
        int s;
        long t;

        void step() {
            int curJump = (int) ((t--) % n);
            int sign = s < m ? 1 : -1;
            s += sign * curJump;
            s %= n;
            if (s < 0) s += n;
        }

        void doLoop() {
            for (int i = 0; i < n; i++) step();
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.NextInt();
            m = in.NextInt();
            s = in.NextInt() - 1;
