        }
        int capacity = (int)data.size();
        int mask = capacity - 2;
        for (int i = hash(key) & mask;; i = (i - 1) & mask) {
            int cur = data[i];
            if (cur == key) {
                data[i + 1] = value;
                return;
            } else if (cur == EMPTY) {
                data[i] = key;
                data[i + 1] = value;
                if (++size > capacity / 4) {
                    data = resize(data, capacity << 1);
                }
                return;
            }
        }
    }

    void deleteKey(int key) {
        if (key == EMPTY) {
            throw invalid_argument("Key cannot be EMPTY");
        }
        int capacity = (int)data.size();
        int mask = capacity - 2;
        for (int i = hash(key) & mask;; i = (i - 1) & mask) {
            int cur = data[i];
            if (cur == key) {
                for (int j = i;;) {
                    int nextIdx = (j - 1) & mask;
                    int k = data[nextIdx];
                    if (k == EMPTY) {
