static vector<IntList> freeLists;

static IntList takeList() {
    if (freeLists.empty()) {
        return IntList();
    } else {
        IntList lst = freeLists.back();
        freeLists.pop_back();
        return lst;
    }
}

static void putList(IntList& list) {
    list.clear();
    freeLists.push_back(list);
}

static int n, m;

static IntList solve(int from, int to) {
    IntList res;
    if (from + 1 == to) {
        res = takeList();
        res.push(from);
        if (from + m > n) {
            res.push(n - from);
            res.push(from - n);
        }
        res.push(m);
        if (from > m) {
            res.push(n - from);
            res.push(from);
        }
        res.push(-from);
    } else {
        int mid = (from + to) >> 1;
        IntList a = solve(from, mid);
        IntList b = solve(mid, to);
        res = takeList();
        int aSize = a.size;
        int bSize = b.size;
        int* aData = a.data.data();
        int* bData = b.data.data();
        for (int i = 0;; i += 2) {
            int bFrom = (i == 0) ? 0 : bData[i - 1];
            int bTo = (i == bSize - 1) ? n : bData[i + 1];
            int bShift = bData[i];
            int aFrom = bFrom + bShift;
            int aTo = bTo + bShift;
            int l = 0, r = aSize - 1;
            while (l < r) {
                int mIdx = (((l + r) >> 2) << 1) + 1;
                if (aData[mIdx] <= aFrom) {
                    l = mIdx + 1;
                } else {
                    r = mIdx - 1;
                }
            }
            int cur = l;
            while (true) {
                res.push(bShift + aData[cur]);
                ++cur;
                if (cur == aSize) break;
                int pos = aData[cur];
                if (pos >= aTo) break;
                res.push(pos - bShift);
                ++cur;
            }
            if (i == bSize - 1) break;
            res.push(bTo);
        }
        putList(a);
        putList(b);
    }
    return res;
}

static void solve() {
    cin >> n >> m;
    int s;
    long long t;
    cin >> s >> t;
    s -= 1;
    long long t_mod = t % n;
    for (long long ct = t_mod; ct != 0; ct--) {
        if (s < m) {
            s += 1;
            if (s >= n) s -= n;
        } else {
            s -= 1;
            if (s < 0) s += n;
        }
    }
    long long cycles = t / n;
    if (cycles > 0) {
        IntList cycleSolve = solve(0, n);
        int csSize = cycleSolve.size;
        int* csData = cycleSolve.data.data();
        IntList cycleList = takeList();
        IntIntMap cycleMap;
        for (int it = 0;; it++) {
            if (it == cycles) break;
            int prev = cycleMap.get(s, -1);
            if (prev >= 0) {
                s = cycleList.get(prev + (int)((cycles - prev) % (it - prev)));
                break;
            }
            cycleList.push(s);
            cycleMap.set(s, it);
            int l = 0, r = csSize - 1;
            while (l < r) {
                int mIdx = (((l + r) >> 2) << 1) + 1;
                if (csData[mIdx] <= s) {
                    l = mIdx + 1;
                } else {
                    r = mIdx - 1;
                }
            }
            s += csData[l];
        }
        putList(cycleList);
    }
    cout << s + 1 << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    try {
        solve();
    } catch (const exception& e) {
        cerr << e.what() << "\n";
        return 1;
    }
    return 0;
}

