            long q = g / r;
            g %= r;

            long temp = g;
            g = r;
            r = temp;

            x -= q * y;

            temp = x;
            x = y;
            y = temp;
        }
        assert(g == 1);
        assert(y == modulus() || y == -modulus());
        return normalize(x);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    Mod998 mod;

    // Precompute inverse factorials up to n + m
    mod.fInv(n + m);

    long phaseSize = 1;
    long p = 1;
    for (int i = 0; p != 0; i++) {
        p = mod.mult(mod.mult(p, n - i), mod.smallInv(n + m - i));
        phaseSize = mod.add(phaseSize, p);
    }

    long answer = 0;
    for (int k = 1; k <= n; k++) {
        long numPhases = mod.mult(m + k, mod.smallInv(k));
        long term = mod.mult(mod.ncr(n, k), mod.mult(numPhases, phaseSize));
        if ((k & 1) == 1)
            answer = mod.add(answer, term);
        else
            answer = mod.subtract(answer, term);
    }

    cout << answer << "\n";

    return 0;
}

