    r -= h * ab;
    h = (r - l + 1) / ab;
    if (h > 2)
        r -= (h - 2) * ab;
    int d = (a > b) ? (a - b) : 1;

    for (int h_idx = 0; h_idx < m; h_idx++) {
        for (int k = 0; k < a - d; k++)
            cc[(a + b) * h_idx + k] = k;
        for (int k = 0; k < d; k++)
            cc[(a + b) * h_idx + a - d + k] = (h_idx % 2 == 0) ? (a - d + k) : (a + k);
    }

    int min_val = a + a;
    for (int k0 = 1; k0 <= d; k0++) {
        for (int k = 0; k < b; k++)
            cc[(a + b) * 0 + a + k] = cc[(a + b) * 0 + a - k0];
        for (int k1 = 1; k1 <= d; k1++) {
            for (int k = 0; k < b; k++)
                cc[(a + b) * 1 + a + k] = cc[(a + b) * 1 + a - k1];
            for (int k2 = 1; k2 <= d; k2++) {
                for (int k = 0; k < b; k++)
                    cc[(a + b) * 2 + a + k] = cc[(a + b) * 2 + a - k2];
                for (int k3 = 1; k3 <= d; k3++) {
                    for (int k = 0; k < b; k++)
                        cc[(a + b) * 3 + a + k] = cc[(a + b) * 3 + a - k3];
                    min_val = std::min(min_val, count(cc, l, r));
                }
            }
        }
    }
    std::cout << min_val << std::endl;
    return 0;
}

