                        flag[rep[i % rep.size()] - 'a'] = true;
                    }
                }

                int ans = 0;
                for (int i = 0; i < 26; i++) {
                    if (flag[i]) ans++;
                }
                min_result = min(ans, min_result);
            }
        }
        cout << min_result << "\n";
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    CMisterBAndBoringGame solver;
    solver.solve();
    return 0;
}

